"use client";

import { useCallback, useId, useMemo, useState } from "react";

import brazil from "./brazil.json";
import { deriveElectionData, electionData } from "./election-data";
import { ElectionLegend } from "./election-legend";
import { ElectionMap } from "./election-map";
import { boundarySource, deriveMapData, mapLayout, type BrazilBoundaries } from "./map-model";
import { NationalResultsChart } from "./national-results-chart";

export default function ChartMap02() {
  // Only source/layout changes rebuild these views. Hover and selection reuse
  // the memoized lookup maps, bar geometry and geographic scene.
  const election = useMemo(() => deriveElectionData(electionData), []);
  const map = useMemo(
    () => deriveMapData(brazil as BrazilBoundaries, election, mapLayout),
    [election],
  );
  const [hoveredRegionCode, setHoveredRegionCode] = useState<string | null>(null);
  const [activeRegionCode, setActiveRegionCode] = useState<string | null>(null);
  const cardId = useId();
  const shownCode = activeRegionCode ?? hoveredRegionCode;
  const shownRegion = shownCode ? (map.regionsByCode.get(shownCode) ?? null) : null;
  const activeRegion = activeRegionCode ? (map.regionsByCode.get(activeRegionCode) ?? null) : null;
  const activate = useCallback((code: string) => {
    setActiveRegionCode(code);
    setHoveredRegionCode(null);
  }, []);
  const clear = useCallback(() => {
    setActiveRegionCode(null);
    setHoveredRegionCode(null);
  }, []);

  return (
    <section className="w-full">
      <header>
        <h2 className="text-center text-2xl font-semibold sm:text-4xl">Brazil Election 2026</h2>
      </header>
      <NationalResultsChart data={election.nationalChart} />
      <div className="relative">
        <ElectionMap
          data={map}
          shownRegion={shownRegion}
          activeRegion={activeRegion}
          cardId={cardId}
          onPreview={setHoveredRegionCode}
          onActivate={activate}
          onClear={clear}
        />
        <div className="space-y-4 lg:absolute lg:bottom-[20%] lg:left-[8%] lg:max-w-80">
          {map.legends.map((legend) => (
            <ElectionLegend key={legend.candidateId} data={legend} />
          ))}
          <p className="text-xs leading-relaxed text-muted-foreground">
            Colour shows the leading candidate. Darker shades show a higher share of valid votes.
          </p>
          <p className="text-sm leading-relaxed text-muted-foreground">
            <strong className="font-medium text-foreground">Overseas voting:</strong>{" "}
            {election.overseasResults.displayResults.map((row, index) => (
              <span key={row.candidateId}>
                {index > 0 && "; "}
                {row.name} {row.percentLabel} ({row.votesLabel} votes)
              </span>
            ))}
            .
          </p>
        </div>
      </div>
      <footer className="mt-4 border-t py-4 text-xs leading-relaxed text-muted-foreground">
        <p>
          Results:{" "}
          <a
            href={election.source.url}
            target="_blank"
            rel="noopener noreferrer"
            className="underline underline-offset-2"
          >
            {election.source.attribution}
          </a>{" "}
          · Boundaries:{" "}
          <a
            href={boundarySource.url}
            target="_blank"
            rel="noopener noreferrer"
            className="underline underline-offset-2"
          >
            {boundarySource.name}
          </a>
        </p>
        <p>
          Election snapshot retrieved {election.source.retrievedAt}; boundaries retrieved{" "}
          {boundarySource.retrievedAt}. Election data licensed{" "}
          <a
            href={election.source.license}
            target="_blank"
            rel="noopener noreferrer"
            className="underline underline-offset-2"
          >
            CC BY-SA 4.0
          </a>
          .
        </p>
      </footer>
    </section>
  );
}

import type { NationalChartData } from "./election-data";

export type NationalResultsChartProps = { data: NationalChartData };

export function NationalResultsChart(props: NationalResultsChartProps) {
  return (
    <figure className="my-6 text-sm sm:text-base">
      <figcaption className="sr-only">
        National first-round presidential results. More than 50% of valid votes is required to win
        outright. The reporting and final-results swatches are a reference key.
      </figcaption>
      <table className="sr-only">
        <caption>National valid votes</caption>
        <thead>
          <tr>
            <th scope="col">Candidate</th>
            <th scope="col">Share</th>
            <th scope="col">Votes</th>
          </tr>
        </thead>
        <tbody>
          {[...props.data.rows, props.data.other].map((row) => (
            <tr key={row.candidateId}>
              <th scope="row">{row.name}</th>
              <td>{row.percentLabel}</td>
              <td>{row.votesLabel}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div
        aria-hidden="true"
        className="grid grid-cols-[100px_minmax(0,1fr)_48px_48px] grid-rows-[auto_6rem_auto] gap-x-2 sm:grid-cols-[180px_minmax(0,1fr)_72px_72px] sm:gap-x-4"
      >
        <div />
        <div className="relative h-14 text-xs text-muted-foreground sm:text-sm">
          <span className="absolute bottom-1 left-0 -translate-x-1/2">0%</span>
          <span className="absolute bottom-1 left-1/3 -translate-x-1/2">25%</span>
          <span className="absolute bottom-1 left-2/3 -translate-x-1/2 whitespace-nowrap text-center leading-tight">
            <strong className="text-foreground">50%</strong>
            <br />
            TO WIN
            <span className="block text-foreground">▼</span>
          </span>
          <span className="absolute bottom-1 left-full -translate-x-1/2">75%</span>
        </div>
        <p className="self-end pb-1 text-right text-xs tracking-wide text-muted-foreground sm:text-sm">
          PCT.
        </p>
        <p className="self-end pb-1 text-right text-xs tracking-wide text-muted-foreground sm:text-sm">
          COUNT
        </p>
        <div className="grid h-full grid-rows-2 items-center text-right">
          {props.data.rows.map((row) => (
            <p key={row.candidateId}>{row.name}</p>
          ))}
        </div>
        <svg
          viewBox="0 0 600 96"
          preserveAspectRatio="none"
          className="h-full w-full overflow-visible"
        >
          <line
            x1={0}
            y1={0}
            x2={0}
            y2={96}
            stroke="currentColor"
            strokeWidth={1}
            vectorEffect="non-scaling-stroke"
          />
          <line
            x1={600}
            y1={0}
            x2={600}
            y2={96}
            stroke="var(--border)"
            strokeWidth={1}
            vectorEffect="non-scaling-stroke"
          />
          {props.data.bars.map((bar) => (
            <rect
              key={bar.key}
              x={bar.x}
              y={bar.y}
              width={bar.width}
              height={bar.height}
              fill={bar.fill}
            />
          ))}
          <line
            x1={400}
            y1={0}
            x2={400}
            y2={96}
            stroke="currentColor"
            strokeWidth={2}
            vectorEffect="non-scaling-stroke"
          />
        </svg>
        <div className="grid h-full grid-rows-2 items-center text-right tabular-nums">
          {props.data.rows.map((row) => (
            <p key={row.candidateId} style={{ color: row.palette.primary }}>
              {row.compactPercentLabel}
            </p>
          ))}
        </div>
        <div className="grid h-24 grid-rows-2 items-center text-right text-muted-foreground tabular-nums">
          {props.data.rows.map((row) => (
            <p key={row.candidateId}>{row.compactVotesLabel}</p>
          ))}
        </div>
        <div className="col-span-4 col-start-1 row-start-3 mt-4 self-start border-t" />
        <div className="col-start-1 row-start-3 self-start flex flex-wrap content-start justify-end gap-x-6 gap-y-3 pt-7 text-right leading-6 sm:col-start-2 sm:justify-start sm:text-left">
          <div className="flex flex-col items-end gap-1 sm:items-start">
            <p className="flex h-6 items-center text-xs tracking-wide text-muted-foreground">
              REPORTING
            </p>
            <div className="flex gap-0.5">
              {props.data.rows.map((row) => (
                <span
                  key={row.candidateId}
                  style={{
                    backgroundColor: row.palette.light,
                    backgroundImage: row.reportingBackground,
                  }}
                  className="size-5 sm:size-7"
                />
              ))}
            </div>
          </div>
          <div className="flex flex-col items-end gap-1 sm:items-start">
            <p className="flex h-6 items-center text-xs tracking-wide text-muted-foreground">
              FINAL RESULTS
            </p>
            <div aria-hidden="true" className="flex gap-0.5">
              {props.data.rows.map((row) => (
                <span
                  key={row.candidateId}
                  style={{ background: row.palette.primary }}
                  className="size-5 sm:size-7"
                />
              ))}
            </div>
          </div>
        </div>
        <p className="col-start-2 row-start-3 self-start justify-self-end translate-x-1/2 pt-7 leading-6 text-muted-foreground">
          Other
        </p>
        <p className="col-start-3 row-start-3 self-start pt-7 text-right leading-6 text-muted-foreground tabular-nums">
          {props.data.other.compactPercentLabel}
        </p>
        <p className="col-start-4 row-start-3 self-start pt-7 text-right leading-6 text-muted-foreground tabular-nums">
          {props.data.other.compactVotesLabel}
        </p>
      </div>
    </figure>
  );
}

import {
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from "react";
// SVG has no native button element; its state groups supply button semantics.
/* eslint-disable jsx-a11y/prefer-tag-over-role, jsx-a11y/no-noninteractive-element-interactions */

import { ElectionResultCard } from "./election-result-card";
import type { DerivedMapData, MapRegion } from "./map-model";

export type ElectionMapProps = {
  data: DerivedMapData;
  shownRegion: MapRegion | null;
  activeRegion: MapRegion | null;
  cardId: string;
  className?: string;
  onPreview: (code: string | null) => void;
  onActivate: (code: string) => void;
  onClear: () => void;
};

type MapViewport = {
  width: number;
  height: number;
  left: number;
  right: number;
  top: number;
  bottom: number;
};
type MapAnchor = { x: number; y: number };

function pointerAnchor(event: PointerEvent | MouseEvent, container: HTMLDivElement): MapAnchor {
  const bounds = container.getBoundingClientRect();
  return {
    x: (event.clientX - bounds.left) / bounds.width,
    y: (event.clientY - bounds.top) / bounds.height,
  };
}

function cardPosition(anchor: MapAnchor, viewport: MapViewport, width: number, height: number) {
  const x = anchor.x * viewport.width;
  const y = anchor.y * viewport.height;
  const rightSpace = viewport.right - x;
  const leftSpace = x - viewport.left;
  const proposedLeft = rightSpace >= leftSpace ? x + 12 : x - width - 12;
  return {
    left: Math.max(viewport.left + 8, Math.min(viewport.right - width - 8, proposedLeft)),
    top: Math.max(viewport.top + 8, Math.min(viewport.bottom - height - 8, y - 24)),
  };
}

export function ElectionMap(props: ElectionMapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const stateRefs = useRef(new Map<string, SVGGElement>());
  const pointerFocus = useRef(false);
  const [viewport, setViewport] = useState<MapViewport>({
    width: props.data.layout.width,
    height: props.data.layout.height,
    left: 0,
    right: props.data.layout.width,
    top: 0,
    bottom: props.data.layout.height,
  });
  const [cardHeight, setCardHeight] = useState(310);
  const [anchor, setAnchor] = useState<MapAnchor>({ x: 0.5, y: 0.5 });
  const [hoveredCode, setHoveredCode] = useState<string | null>(null);
  // Keep the last content mounted so CSS can animate dismissal without timers.
  const [lastCard, setLastCard] = useState({
    region: props.shownRegion,
    selected: Boolean(props.activeRegion),
  });
  if (
    props.shownRegion &&
    (lastCard.region !== props.shownRegion || lastCard.selected !== Boolean(props.activeRegion))
  ) {
    setLastCard({ region: props.shownRegion, selected: Boolean(props.activeRegion) });
  }
  const lastShown = lastCard.region;
  const shown = props.shownRegion;
  const selected = props.activeRegion;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const measure = () => {
      const bounds = container.getBoundingClientRect();
      setViewport({
        width: bounds.width,
        height: bounds.height,
        left: Math.max(0, -bounds.left),
        right: Math.min(bounds.width, window.innerWidth - bounds.left),
        top: Math.max(0, -bounds.top),
        bottom: Math.min(bounds.height, window.innerHeight - bounds.top),
      });
    };
    const observer = new ResizeObserver(measure);
    observer.observe(container);
    window.addEventListener("scroll", measure, true);
    window.addEventListener("resize", measure);
    return () => {
      observer.disconnect();
      window.removeEventListener("scroll", measure, true);
      window.removeEventListener("resize", measure);
    };
  }, []);

  const hasContent = Boolean(lastShown);
  useEffect(() => {
    const card = cardRef.current;
    if (!card) return;
    const observer = new ResizeObserver(() => setCardHeight(card.getBoundingClientRect().height));
    observer.observe(card);
    return () => observer.disconnect();
  }, [hasContent]);

  useEffect(() => {
    const dismiss = () => {
      setHoveredCode(null);
      props.onClear();
      // Move focus to a stable, non-Tab-stop container, not back to the state.
      if (containerRef.current?.contains(document.activeElement))
        containerRef.current.focus({ preventScroll: true });
    };
    const keydown = (event: globalThis.KeyboardEvent) => {
      pointerFocus.current = false;
      if (event.key === "Escape" && (props.activeRegion || props.shownRegion)) {
        event.preventDefault();
        dismiss();
      }
    };
    const pointerdown = (event: globalThis.PointerEvent) => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      if (
        containerRef.current?.contains(target) &&
        (target.closest("[data-map-state]") || cardRef.current?.contains(target))
      )
        return;
      if (props.activeRegion || props.shownRegion) {
        setHoveredCode(null);
        props.onClear();
        if (containerRef.current?.contains(document.activeElement))
          containerRef.current.focus({ preventScroll: true });
      }
    };
    window.addEventListener("keydown", keydown);
    window.addEventListener("pointerdown", pointerdown);
    return () => {
      window.removeEventListener("keydown", keydown);
      window.removeEventListener("pointerdown", pointerdown);
    };
  }, [props]);

  const dismiss = () => {
    setHoveredCode(null);
    props.onClear();
    containerRef.current?.focus({ preventScroll: true });
  };
  const activateFromKeyboard = (state: MapRegion) => {
    setAnchor({ x: state.x / props.data.layout.width, y: state.y / props.data.layout.height });
    props.onActivate(state.code);
  };
  const trackPointer = (event: PointerEvent<SVGGElement>, state: MapRegion) => {
    if (event.pointerType === "touch") return;
    setHoveredCode(state.code);
    if (selected || !containerRef.current) return;
    setAnchor(pointerAnchor(event, containerRef.current));
    props.onPreview(state.code);
  };
  const handleCloseKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key !== "Tab" || !selected) return;
    const index = props.data.regions.findIndex((region) => region.code === selected.code);
    const destination = event.shiftKey ? selected : props.data.regions[index + 1];
    if (destination) {
      event.preventDefault();
      stateRefs.current.get(destination.code)?.focus();
    }
    // At the last state, natural Tab leaves the map and the blur handler clears it.
  };
  const cardWidth = Math.max(
    0,
    Math.min(viewport.width < 640 ? 220 : 320, viewport.right - viewport.left - 16),
  );
  const maxHeight = Math.max(0, viewport.bottom - viewport.top - 16);
  const position = cardPosition(anchor, viewport, cardWidth, Math.min(cardHeight, maxHeight));

  return (
    <div
      ref={containerRef}
      aria-label="Election map and results"
      role="group"
      tabIndex={-1}
      className={`relative outline-none ${props.className ?? ""}`}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredCode(null);
          props.onClear();
        }
      }}
      onPointerLeave={() => {
        setHoveredCode(null);
        if (!selected) props.onPreview(null);
      }}
    >
      <svg
        aria-label="Brazil first-round presidential results. Tab through states to explore."
        role="group"
        viewBox={`0 0 ${props.data.layout.width} ${props.data.layout.height}`}
        className="block h-auto w-full"
      >
        <g aria-hidden="true" pointerEvents="none">
          {props.data.regions.map((state) => (
            <path
              key={state.code}
              d={state.path}
              fill={state.fill}
              stroke="#ffffff"
              strokeWidth={1}
              style={{ filter: hoveredCode === state.code ? "brightness(1.08)" : "brightness(1)" }}
              className="transition-[filter] duration-120 motion-reduce:transition-none"
            />
          ))}
        </g>
        {props.data.regions.map((state) => {
          const external = state.calloutPath !== null;
          return (
            <g
              key={state.code}
              ref={(node) => {
                if (node) stateRefs.current.set(state.code, node);
                else stateRefs.current.delete(state.code);
              }}
              data-map-state={state.code}
              aria-label={state.accessibleLabel}
              aria-describedby={shown?.code === state.code ? props.cardId : undefined}
              aria-pressed={selected?.code === state.code}
              role="button"
              tabIndex={0}
              className="cursor-pointer outline-none"
              onClick={(event) => {
                pointerFocus.current = false;
                if (event.detail && containerRef.current)
                  setAnchor(pointerAnchor(event, containerRef.current));
                else
                  setAnchor({
                    x: state.x / props.data.layout.width,
                    y: state.y / props.data.layout.height,
                  });
                props.onActivate(state.code);
              }}
              onFocus={() => {
                if (!pointerFocus.current) activateFromKeyboard(state);
              }}
              onKeyDown={(event) => {
                pointerFocus.current = false;
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  activateFromKeyboard(state);
                }
                if (event.key === "Tab" && !event.shiftKey && selected?.code === state.code) {
                  event.preventDefault();
                  closeRef.current?.focus();
                }
                if (event.key === "Tab" && event.shiftKey) {
                  const index = props.data.regions.findIndex(
                    (region) => region.code === state.code,
                  );
                  const previous = props.data.regions[index - 1];
                  if (previous) {
                    event.preventDefault();
                    stateRefs.current.get(previous.code)?.focus();
                    requestAnimationFrame(() => closeRef.current?.focus());
                  }
                }
              }}
              onPointerDown={() => {
                pointerFocus.current = true;
              }}
              onPointerEnter={(event) => trackPointer(event, state)}
              onPointerMove={(event) => trackPointer(event, state)}
              onPointerLeave={() => {
                setHoveredCode(null);
                if (!selected) props.onPreview(null);
              }}
            >
              <path d={state.path} fill="transparent" />
              {external && (
                <path
                  aria-hidden="true"
                  d={state.calloutPath ?? undefined}
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={1.2}
                />
              )}
              <text
                aria-hidden="true"
                x={state.label[0]}
                y={state.label[1]}
                fill={external ? "currentColor" : "#ffffff"}
                textAnchor="middle"
                dominantBaseline="middle"
                fontSize={23}
                fontWeight={700}
                paintOrder="stroke"
                stroke={external ? "var(--card)" : "#00000030"}
                strokeWidth={3}
              >
                {state.code}
              </text>
              {external && (
                <rect
                  x={state.label[0] - 24}
                  y={state.label[1] - 20}
                  width={48}
                  height={40}
                  fill="transparent"
                />
              )}
            </g>
          );
        })}
        {selected && (
          <path
            aria-hidden="true"
            d={selected.path}
            fill="none"
            stroke="#111111"
            strokeWidth={3}
            vectorEffect="non-scaling-stroke"
            pointerEvents="none"
          />
        )}
      </svg>
      {lastShown && (
        <div
          ref={cardRef}
          id={props.cardId}
          aria-hidden={!shown}
          inert={!shown}
          role={lastCard.selected ? "group" : "tooltip"}
          aria-label={lastCard.selected ? `${lastShown.result.name} results` : undefined}
          style={{
            ...position,
            width: cardWidth,
            maxHeight,
            opacity: shown ? 1 : 0,
            transform: shown ? "translateY(0)" : "translateY(4px)",
            transitionProperty: lastCard.selected
              ? "opacity, transform, left, top"
              : "opacity, transform",
          }}
          className={`absolute z-10 overflow-auto rounded-md transition-[opacity,transform] duration-120 starting:opacity-0 starting:translate-y-1 motion-reduce:transition-none motion-reduce:duration-0 ${shown && selected ? "pointer-events-auto" : "pointer-events-none"}`}
        >
          <ElectionResultCard
            result={lastShown.result}
            dense={viewport.width < 640}
            closeButtonRef={closeRef}
            onClose={lastCard.selected ? dismiss : undefined}
            onCloseKeyDown={handleCloseKeyDown}
          />
        </div>
      )}
    </div>
  );
}

import type { KeyboardEvent, RefObject } from "react";

import type { RegionResult } from "./election-data";

export type ElectionResultCardProps = {
  result: RegionResult;
  compact?: boolean;
  dense?: boolean;
  closeButtonRef?: RefObject<HTMLButtonElement | null>;
  onClose?: () => void;
  onCloseKeyDown?: (event: KeyboardEvent<HTMLButtonElement>) => void;
};

function compactCandidateName(name: string) {
  return name === "Luiz Inácio Lula da Silva" ? "Lula" : name;
}

export function ElectionResultCard({ closeButtonRef, ...props }: ElectionResultCardProps) {
  return (
    <div
      className={
        props.compact
          ? "rounded-lg border border-black/10 bg-white p-4 text-neutral-800"
          : props.dense
            ? "rounded-lg border border-black/10 bg-white p-2.5 text-neutral-800 shadow-lg"
            : "rounded-md border border-black/10 bg-white p-5 text-neutral-800 shadow-xl"
      }
    >
      <p
        className={
          props.dense
            ? "text-base font-semibold tracking-tight"
            : "text-2xl font-medium tracking-tight"
        }
      >
        {props.result.name}
      </p>
      <p
        style={{
          color: props.result.leadColor,
        }}
        className={props.dense ? "mt-1 text-xs font-semibold" : "mt-2 text-base font-bold"}
      >
        {props.result.leadLabel}
      </p>
      <p
        className={
          props.dense ? "mt-0.5 text-[11px] text-neutral-500" : "mt-1 text-sm text-neutral-500"
        }
      >
        {props.dense && props.result.leader
          ? `${compactCandidateName(props.result.leader.name)} +${props.result.leadPercentPoints.toFixed(2)} pts`
          : props.result.leadPointsLabel}
      </p>
      <dl className={props.dense ? "mt-3 space-y-2" : "mt-4 space-y-3"}>
        {props.result.displayResults.map((row) => (
          <div
            key={row.candidateId}
            className={`grid grid-cols-[minmax(0,1fr)_auto] gap-x-2 ${props.dense ? "text-xs" : "text-sm"}`}
          >
            <dt title={row.name} className="flex min-w-0 items-center gap-1.5">
              <span
                aria-hidden="true"
                style={{ background: row.palette.primary }}
                className={
                  props.dense ? "size-2 shrink-0 rounded-full" : "size-2.5 shrink-0 rounded-full"
                }
              />
              <span className="truncate">
                {props.dense ? compactCandidateName(row.name) : row.name}
              </span>
            </dt>
            <dd className="font-bold tabular-nums">{row.percentLabel}</dd>
            <dd
              className={`col-span-2 mt-0.5 pl-3.5 font-normal text-neutral-500 tabular-nums ${props.dense ? "text-[10px]" : "text-xs"}`}
            >
              {row.votesLabel} votes
            </dd>
          </div>
        ))}
      </dl>
      {props.onClose && (
        <button
          ref={closeButtonRef}
          type="button"
          aria-label={`Close ${props.result.name} results`}
          className={`min-h-10 w-full rounded-md border-t text-neutral-600 transition-colors hover:bg-neutral-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-800 motion-reduce:transition-none ${props.dense ? "mt-2 text-xs" : "mt-3 text-sm"}`}
          onClick={props.onClose}
          onKeyDown={props.onCloseKeyDown}
        >
          Close
        </button>
      )}
    </div>
  );
}

